import{_ as l,a8 as d,o as i,c as h,ah as p,a as e,a3 as a,K as r,L as b}from"./chunks/framework.DwkUJ0oD.js";import"./chunks/theme.DXFaLrA7.js";const _=JSON.parse('{"title":"Jev 与传统 LLM 的区别","description":"","frontmatter":{"title":"Jev 与传统 LLM 的区别","abstract":"Jev 与传统 LLM 的对比分析，从任务定位、输出形态、幻觉控制与置信度机制等维度讲解两者在解决决策问题上的差异。","created":"2026-09-23T00:00:00.000Z","tags":["AI","Jev","LLM","对比分析"],"type":"对比分析","related":["[[Jev-MOC]]","[[Jev-概述]]","[[Jev-与Agent的协作架构]]"],"reference":"","category":["🧩 AI框架与Agent","Jev"]},"headers":[],"relativePath":"vault/Knowledge/AI/Jev-与传统LLM的区别.md","filePath":"vault/Knowledge/AI/Jev-与传统LLM的区别.md","lastUpdated":1790655645000}'),g={name:"vault/Knowledge/AI/Jev-与传统LLM的区别.md"};function v(k,t,L,c,m,u){const n=d("VPNolebaseInlineLinkPreview"),s=d("NolebaseGitContributors"),o=d("NolebaseGitChangelog");return i(),h("div",null,[t[5]||(t[5]=p('<h1 id="jev-与传统-llm-的区别" tabindex="-1">Jev 与传统 LLM 的区别 <a class="header-anchor" href="#jev-与传统-llm-的区别" aria-label="Permalink to “Jev 与传统 LLM 的区别”">​</a></h1><p>最重要的区别不是「一个大、一个小」，而是<strong>两者从一开始就在解决不同的问题</strong>。</p><h2 id="逐项对比" tabindex="-1">逐项对比 <a class="header-anchor" href="#逐项对比" aria-label="Permalink to “逐项对比”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>传统 LLM（GPT / Claude 等）</th><th>Jev</th></tr></thead><tbody><tr><td>核心目标</td><td>生成内容</td><td>做决策</td></tr><tr><td>输出形式</td><td>自由文本、代码、JSON 等</td><td>结构化决策</td></tr><tr><td>典型任务</td><td>对话、写作、代码、分析</td><td>分类、评分、判断、路由</td></tr><tr><td>输出空间</td><td>开放</td><td>预先定义</td></tr><tr><td>程序使用</td><td>经常需要解析和校验</td><td>可直接进入业务逻辑</td></tr><tr><td>生成方式</td><td>以自回归生成 Token 为核心</td><td>针对决策进行并行评估</td></tr><tr><td>置信度</td><td>通常不是主要接口</td><td>决策概率是核心能力之一</td></tr><tr><td>延迟</td><td>与模型规模和输出长度相关</td><td>目标为极低延迟</td></tr><tr><td>通用性</td><td>很强</td><td>较窄</td></tr><tr><td>最适合</td><td>复杂思考与内容生成</td><td>高频、小范围的智能判断</td></tr></tbody></table><h2 id="为什么-jev-更快" tabindex="-1">为什么 Jev 更快 <a class="header-anchor" href="#为什么-jev-更快" aria-label="Permalink to “为什么 Jev 更快”">​</a></h2><p>传统 LLM 的基本特征是<strong>逐 Token 自回归生成</strong>，后一个 Token 依赖前一个 Token，因此生成长文本必须做大量连续解码：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>Token 1 → Token 2 → Token 3 → Token 4 → ……</span></span></code></pre></div><p>Jev 不需要回答「下一句话应该怎么写」，而是在一个<strong>已经定义好的决策空间</strong>里做判断，候选结果本身是确定的：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>退款 0.91 ｜ 物流 0.05 ｜ 技术 0.03 ｜ 投诉 0.01</span></span></code></pre></div><p>因此它可以对这些候选做更直接的并行评估（官方称为 Parallel Sampler，并行采样）。这也是为什么 Jev 的速度优势不只来自「模型更小」，而是<strong>从模型设计、采样方式到训练目标都针对决策任务做了优化</strong>。</p><h2 id="两个角色" tabindex="-1">两个角色 <a class="header-anchor" href="#两个角色" aria-label="Permalink to “两个角色”">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>承担</th></tr></thead><tbody><tr><td><strong>LLM：聪明的分析师</strong></td><td>思考、推理、写作、解释、写代码、生成内容</td></tr><tr><td><strong>Jev：高速决策引擎</strong></td><td>判断、分类、评分、路由、筛选、审核</td></tr></tbody></table><h2 id="是替代品吗" tabindex="-1">是替代品吗 <a class="header-anchor" href="#是替代品吗" aria-label="Permalink to “是替代品吗”">​</a></h2>',13)),e("p",null,[t[1]||(t[1]=a("不是。更准确的说法是：",-1)),t[2]||(t[2]=e("strong",null,"Jev 是生成式大模型的补充层",-1)),t[3]||(t[3]=a("，与 LLM、Code 各承担一段职责。三者的分工与典型架构见 ",-1)),r(n,{href:"/nebula-blog/vault/Knowledge/AI/Jev-与Agent的协作架构.html"},{default:b(()=>[...t[0]||(t[0]=[a("Jev-与Agent的协作架构",-1)])]),_:1}),t[4]||(t[4]=a("。",-1))]),t[6]||(t[6]=e("p",null,[e("em",null,"（内容由AI生成，仅供参考）")],-1)),r(s),r(o)])}const x=l(g,[["render",v]]);export{_ as __pageData,x as default};
